  const three = (f, pump = "250") =&gt; [[750, 1000], [1000, 1150], [1000, 800]].forEach(([x, y]) =&gt; f.drill({ x, y, pump }));
  const inj = (f, pts) =&gt; pts.forEach(([x, y]) =&gt; f.drill({ x, y, type: "inj", choke: 16 }));
